INSERT INTO example_sentences (id, entry_id, japanese_text, reading, source_code) VALUES
(1, 1, '毎朝パンを食べます。', 'まいあさパンをたべます。', 'TATOEBA'),
(2, 2, 'お茶を飲みましょう。', 'おちゃをのみましょう。', 'TATOEBA'),
(3, 3, '学校へ行きます。', 'がっこうへいきます。', 'TATOEBA'),
(4, 4, '明日友達が来ます。', 'あしたともだちがきます。', 'TATOEBA'),
(5, 5, '日本語の本を読みます。', 'にほんごのほんをよみます。', 'TATOEBA'),
(6, 6, '日本語は面白いです。', 'にほんごはおもしろいです。', 'TATOEBA'),
(7, 7, '新しい靴を買いました。', 'あたらしいくつをかいました。', 'TATOEBA'),
(8, 8, 'このお寺は古いです。', 'このおてらはふるいです。', 'TATOEBA'),
(9, 9, '先生と日本語で話します。', 'せんせいとにほんごではなします。', 'TATOEBA'),
(10, 10, '手紙を書きます。', 'てがみをかきます。', 'TATOEBA'),
(11, 11, '音楽を聞くのが好きです。', 'おんがくをきくのがすきです。', 'TATOEBA'),
(12, 12, '一緒に映画を見ませんか。', 'いっしょにえいがをみませんか。', 'TATOEBA'),
(13, 13, '山田先生は親切です。', 'やまだせんせいはしんせつです。', 'TATOEBA'),
(14, 14, '私は大学の学生です。', 'わたしはだいがくのがくせいです。', 'TATOEBA'),
(15, 15, '友達と遊びます。', 'ともだちとあそびます。', 'TATOEBA'),
(16, 16, '母に荷物を送りました。', 'ははにもつをおくりました。', 'TATOEBA'),
(17, 17, '空港へ客を迎えに行きます。', 'くうこうへきゃくをむかえにいきます。', 'TATOEBA'),
(18, 18, '時計を直してもらいました。', 'とけいをなおしてもらいました。', 'TATOEBA'),
(19, 19, '彼は誰にでも親切です。', 'かれはだれにでもしんせつです。', 'TATOEBA'),
(20, 20, '地下鉄はとても便利です。', 'ちかてつはとてもべんりです。', 'TATOEBA'),
(21, 21, '実験は無事に成功した。', 'じっけんはぶじにせいこうした。', 'TATOEBA'),
(22, 22, '最後まで夢を諦めないでください。', 'さいごまでゆめをあきらめないでください。', 'TATOEBA'),
(23, 23, '努力は必ず報われる。', 'どりょくはかならずむくわれる。', 'TATOEBA'),
(24, 24, '困難を克服してゴールに達した。', 'こんなんをこくふくしてゴールにたっした。', 'TATOEBA'),
(25, 25, '曖昧な返事は避けたほうがいい。', 'あいまいなへんじはさけたほうがいい。', 'TATOEBA'),
(26, 26, '証拠を隠蔽することは許されない。', 'しょうこをいんぺいすることはゆるされない。', 'TATOEBA'),
(27, 27, 'この調査結果は興味深い事実を示唆している。', 'このちょうさけっかはきょうみぶかいじじつをしさしている。', 'TATOEBA');
